import java.util.Scanner;

public class Main {
    static long[] pattern = new long[30];

    static long getMinCost(long n) {
        if (n <= 6) return n;
        long firstChoice = (long) 1e9;
        long secondChoice = (long) 1e9;
        for (int i = 0; i < 20; i++) {
            if (pattern[i] > n) {
                firstChoice = getMinCost(n % pattern[i - 1]) + i * (n / pattern[i - 1]);
                break;
            }
        }
        for (int i = 0; i < 20; i++) {
            if (pattern[i] >= n) {
                if (pattern[i] - n >= n) {
                    firstChoice = (long) 1e9;
                } else {
                    secondChoice = getMinCost(pattern[i] - n) + (i + 1);
                }
                break;
            }
        }
        return Math.min(firstChoice, secondChoice);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        pattern[0] = 1;
        for (int i = 1; i < 18; i++) {
            pattern[i] = pattern[i - 1] * 10 + 1;
        }
        long val = sc.nextLong();
        System.out.println(getMinCost(val));
        sc.close();
    }
}
